WITH scored AS (SELECT *, AVG(monthly_fee) OVER w_recent AS last7_avg_monthly_fee, COUNT(monthly_fee) OVER w_recent AS last7_count_monthly_fee, MAX(monthly_fee) OVER w_recent AS last7_max_monthly_fee FROM subscriptions WHERE start_date < '2025-06-09' WINDOW w_recent AS (PARTITION BY customer_id ORDER BY end_date, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW)) SELECT customer_id, DATE_TRUNC('QUARTER', start_date) AS quarter_start, SUM(CASE WHEN status = 'PAUSED' THEN last7_avg_monthly_fee ELSE 0 END) AS paused_last7_avg_monthly_fee, APPROX_PERCENTILE(last7_max_monthly_fee, ARRAY(0.25, 0.5, 0.75)) AS last7_max_monthly_fee_quartiles, GROUPING_ID() AS grouping_id FROM scored GROUP BY GROUPING SETS ((customer_id, DATE_TRUNC('QUARTER', start_date)), (customer_id)) HAVING SUM(CASE WHEN status = 'PAUSED' THEN last7_avg_monthly_fee ELSE 0 END) > 0 ORDER BY quarter_start NULLS FIRST
